from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_upload_time(value: Any) -> datetime | None:
    """Parse an ``upload_time_iso_8601`` value, returning ``None`` on failure."""
    if not isinstance(value, str) or not value:
        return None
    text = value
    # ``datetime.fromisoformat`` on Python < 3.11 does not accept a trailing "Z".
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version) and its aggregated metadata."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(
        cls, version: Version, distributions: list[dict[str, Any]]
    ) -> Release | None:
        """Build a ``Release`` from a version's list of distribution dicts.

        Returns ``None`` if no distribution has a parseable
        ``upload_time_iso_8601`` field.
        """
        upload_times = [
            t
            for dist in distributions
            if (t := _parse_upload_time(dist.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is considered yanked only if every distribution is yanked.
        yanked = all(bool(dist.get("yanked", False)) for dist in distributions)

        # Use the first non-empty, valid ``requires_python`` across distributions.
        requires_python: SpecifierSet | None = None
        for dist in distributions:
            raw = dist.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
                break
            except InvalidSpecifier:
                continue

        return cls(
            version=version,
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass(frozen=True)
class Package:
    """A PyPI package and its releases."""

    name: str
    releases: dict[Version, Release]

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a ``Package``.

        Releases with no distributions, releases whose distributions all lack a
        parseable upload time, and releases whose version cannot be parsed as a
        valid PEP 440 version are dropped.
        """
        info = data.get("info") or {}
        name = info.get("name") or data.get("name") or ""

        releases: dict[Version, Release] = {}
        for version_str, distributions in (data.get("releases") or {}).items():
            if not distributions:
                continue
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            release = Release.from_distributions(version, distributions)
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        """The highest stable, non-yanked version, or ``None`` if none exists."""
        candidates = [
            version
            for version, release in self.releases.items()
            if not version.is_prerelease
            and not version.is_devrelease
            and not release.yanked
        ]
        return max(candidates) if candidates else None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the ``Release`` for ``version``, or ``None`` if not present."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
