from __future__ import annotations

import asyncio
import json
import os
import time
import urllib.error
import urllib.request
from typing import Any, Iterable

from ._models import Package

DEFAULT_BASE_URL = "https://pypi.org"

# Total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3
# Status codes that are considered transient and worth retrying.
_RETRYABLE_STATUS = frozenset({429, 500, 502, 503, 504})
# Base backoff (seconds) between retries.
_RETRY_BACKOFF = 0.5

# In-memory cache mapping package name -> Package.
_cache: dict[str, Package] = {}


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


def _base_url() -> str:
    base = os.environ.get("PYPI_URL")
    if base is None:
        base = DEFAULT_BASE_URL
    return base.rstrip("/")


def _fetch_json(name: str) -> dict[str, Any]:
    url = f"{_base_url()}/pypi/{name}/json"
    last_error: Exception | None = None

    for attempt in range(1, _MAX_ATTEMPTS + 1):
        try:
            with urllib.request.urlopen(url) as response:
                body = response.read()
            break
        except urllib.error.HTTPError as e:
            # ``HTTPError`` is a subclass of ``URLError`` so it must come first.
            if e.code == 404:
                raise PyPIError(f"Package not found: {name}") from e
            if e.code in _RETRYABLE_STATUS:
                last_error = e
                if attempt < _MAX_ATTEMPTS:
                    time.sleep(_RETRY_BACKOFF * attempt)
                continue
            raise PyPIError(f"HTTP {e.code} error fetching {name}") from e
        except (urllib.error.URLError, ConnectionResetError) as e:
            last_error = e
            if attempt < _MAX_ATTEMPTS:
                time.sleep(_RETRY_BACKOFF * attempt)
            continue
    else:
        raise PyPIError(
            f"Failed to fetch {name} after {_MAX_ATTEMPTS} attempts"
        ) from last_error

    try:
        data = json.loads(body)
    except (ValueError, json.JSONDecodeError) as e:
        raise PyPIError(f"Failed to parse response for {name}") from e

    if not isinstance(data, dict):
        raise PyPIError(
            f"Unexpected response for {name}: expected a JSON object, "
            f"got {type(data).__name__}"
        )

    return data


def get_package(name: str) -> Package:
    """Fetch package metadata from the PyPI JSON API, caching the result.

    Repeated calls with the same name make only one HTTP request.
    """
    if name in _cache:
        return _cache[name]
    package = Package.from_json(_fetch_json(name))
    _cache[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _cache.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    names = list(names)
    return list(await asyncio.gather(*(aget_package(name) for name in names)))
